class Solution { public:vector<vector<int>> onesMinusZeros(vector<vector<int>>& grid){int rows=grid.size(),cols=grid[0].size();vector<int> rowOnes(rows),colOnes(cols);for(int row=0;row<rows;++row)for(int col=0;col<cols;++col)if(grid[row][col]){++rowOnes[row];++colOnes[col];}vector<vector<int>> answer(rows,vector<int>(cols));for(int row=0;row<rows;++row)for(int col=0;col<cols;++col)answer[row][col]=2*(rowOnes[row]+colOnes[col])-rows-cols;return answer;} };
